import React, { useState } from 'react';
import Table from './components/Table';
import './App.css';

    function App() {
        const [tables, setTables] = useState(() => {
            // Initialize tables from localStorage if any exist
            const existingTables = Object.keys(localStorage)
                .filter(key => key.startsWith('table_'))
                .map(key => parseInt(key.split('_')[1]));
            return existingTables.length > 0 ? existingTables : [];
        });

        const [selectedTable, setSelectedTable] = useState(null);
        const [tableTotals, setTableTotals] = useState(() => {
            // Initialize totals from localStorage
            const existingTotals = {};
            Object.keys(localStorage)
                .filter(key => key.startsWith('table_'))
                .forEach(key => {
                    const tableId = parseInt(key.split('_')[1]);
                    const data = JSON.parse(localStorage.getItem(key));
                    existingTotals[tableId] = data;
                });
            return existingTotals;
        });

        const addTable = () => {
            try {
                const newTableId = tables.length > 0 ? Math.max(...tables) + 1 : 1;
                const tableKey = `table_${newTableId}`;
                
                const initialData = {
                    drinks: { items: [], total: 0 },
                    beverages: { items: [], total: 0 },
                    food: { items: [], total: 0 },
                    others: { items: [], total: 0 },
                    grandTotal: 0
                };

                localStorage.setItem(tableKey, JSON.stringify(initialData));
                setTableTotals(prev => ({
                    ...prev,
                    [newTableId]: initialData
                }));

                setTables(prevTables => [...prevTables, newTableId]);
                setSelectedTable(newTableId);
            } catch (error) {
                console.error('Error adding table:', error);
                alert('Failed to add table. Please try again.');
            }
        };

        const updateTableTotals = (tableId, newTotals) => {
            setTableTotals(prev => ({
                ...prev,
                [tableId]: newTotals
            }));
        };

        return (
            <div className="App">
                <div className="sidebar">
                    <button className="add-table-btn" onClick={addTable}>Add Table</button>
                    <div className="table-list">
                        {tables.map(tableId => (
                            <div 
                                key={tableId} 
                                className={`table-item ${selectedTable === tableId ? 'active' : ''}`}
                                onClick={() => selectTable(tableId)}
                            >
                                Table {tableId}
                                {tableTotals[tableId] && 
                                    <div className="table-total">₹{tableTotals[tableId].grandTotal.toFixed(2)}</div>
                                }
                            </div>
                        ))}
                    </div>
                </div>
                <div className="main-content">
                    {selectedTable && 
                        <Table 
                            tableId={selectedTable} 
                            onUpdateTotals={(totals) => updateTableTotals(selectedTable, totals)}
                        />
                    }
                </div>
            </div>
        );
    }

    export default App;
